"""Synthetic-only safety checks; all generated bytes stay below owned work/.

Tests of backup plans and archive creation (storage_backup).
"""
from __future__ import annotations

import json
import unittest
from pathlib import Path

# Imported first: test_storage_policy puts scripts/ on sys.path for the product imports below.
from test_storage_policy import NativeStorageFixture
from scoped_fs import ScopedFSError
from private_workspace import ensure_private_directory, ensure_private_file
from storage_ops import StorageRefusal, plan_sha256


class NativeStorageTests(NativeStorageFixture, unittest.TestCase):
    def test_private_archive_probe_and_records_actual_permissions(self):
        plan, backup = self.backup(selected=["r001/readme.txt"])
        restored = self.probe(backup)
        for path in (Path(backup["archive"]), Path(backup["manifest"]),
                     self.output / backup["attempt"], self.output / restored["attempt"],
                     self.output / ("outcome-backup-" + plan_sha256(plan) + ".json"),
                     self.output / ("outcome-restore-" + restored["plan_sha256"] + ".json"),
                     Path(restored["destination"]) / "r001" / "readme.txt"):
            ensure_private_file(path)
        ensure_private_directory(Path(restored["destination"]))
        ensure_private_directory(Path(restored["destination"]) / "r001")

    def test_verified_backup_restore_and_immutable_archive(self):
        plan, receipt = self.backup()
        attempt = json.loads((self.output / receipt["attempt"]).read_bytes())
        self.assertNotIn("exact_plan", attempt)
        self.assertEqual(attempt["plan_sha256"], plan_sha256(plan))
        self.assertEqual(attempt["entry_count"], len(plan["files"]))
        self.assertEqual(json.loads((self.output / attempt["plan_file"]).read_bytes()), plan)
        verified = self.service.verify_backup(receipt=receipt)
        self.assertTrue(verified["verified"])
        self.assertTrue(self.service.verify_outcome(plan=plan, expected_plan_sha256=plan_sha256(plan), receipt=receipt)["verification_passed"])
        self.assertFalse(receipt["encryption"])
        self.assertEqual(len(verified["manifest"]["files"]), 4)
        restore = self.service.plan_restore(receipt=receipt, destination=self.output / "restored")
        outcome = self.service.restore_backup(plan=restore, expected_plan_sha256=plan_sha256(restore))
        self.assertTrue(outcome["verified"])
        self.assertTrue(self.service.verify_outcome(plan=restore, expected_plan_sha256=plan_sha256(restore), receipt=outcome)["verification_passed"])
        self.assertEqual((self.output / "restored" / "r001" / "readme.txt").read_bytes(), b"fictional document\n")
        self.assertEqual((self.output / "restored" / "r001" / "notes" / "draft.md").read_bytes(), b"fictional draft\n")
        with self.assertRaises((StorageRefusal, ScopedFSError, FileExistsError)):
            self.service.create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))
        with self.assertRaises((StorageRefusal, ScopedFSError, FileExistsError)):
            self.service.plan_restore(receipt=receipt, destination=self.output / "restored")

    def test_skipped_unbacked_files_visible_and_required_recovery_holds(self):
        inventory = self.inventory()
        selected = ["r001/readme.txt"]
        plan, receipt = self.backup(inventory, selected)
        self.assertTrue(any(row["key"] == "r001/copy.txt" and "not backed up" in row["reason"] for row in plan["skipped"]))
        with self.assertRaisesRegex(StorageRefusal, "Required recovery"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True)
        with self.assertRaisesRegex(StorageRefusal, "restoration probe"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt)
        probe = self.probe(receipt)
        with self.assertRaisesRegex(StorageRefusal, "does not cover"):
            self.service.plan_cleanup(inventory=inventory, selected=["r001/copy.txt"], quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt, recovery_verification=probe)
        with self.assertRaisesRegex(StorageRefusal, "protected"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt, protected=selected)


if __name__ == "__main__":
    unittest.main(verbosity=2)
